/* Personal, offline learning. All text imported by the learner is escaped before rendering. */
(() => {
  'use strict';
  const E=window.LearningEngine,course=window.CURRICULUM,heroes=window.HEROES;
  const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const key='jixia-learning-v1',day=()=>new Date().toLocaleDateString('sv-SE');
  let state=E.newState(),storageError='',view='adventure',filter='全部',session=null,toastTimer,voiceStatus='',semester='全部';
  const voice=new HeroVoicePlayer(text=>{voiceStatus=text;document.querySelectorAll('[data-voice-status]').forEach(el=>el.textContent=text);});
  const dialog=$('lesson-dialog');dialog.className='lesson-dialog';
  try {
    const raw=localStorage.getItem(key);
    if(raw){const old=JSON.parse(raw);state=E.restore({kind:'jixia-save',version:1,state:old});
      if(!old.voiceVersion){state.sound=true;state.voiceVersion=2;}
      if(old.activity?.date===day() && ['answered','completed','reviewed'].every(k=>Number.isInteger(old.activity[k])&&old.activity[k]>=0))state.activity=old.activity;
      if(old.session && ['story','practice','review'].includes(old.session.mode) && ['story','question','result'].includes(old.session.phase) && Array.isArray(old.session.questions) && old.session.questions.length>0 && old.session.questions.length<=30 && Number.isInteger(old.session.index) && old.session.index>=0 && old.session.index<old.session.questions.length){
        const pending=old.session;pending.questions=pending.questions.map(q=>E.validateQuestion(q));
        if(Number.isInteger(pending.correct)&&pending.correct>=0&&pending.correct<=pending.questions.length && Number.isFinite(pending.gained))state.session=pending;
      }
    }
  } catch {storageError='本地存档无法读取，暂以新旅程打开。原存档未自动覆盖，可先导出原始存档保留。';}
  function persist(){if(storageError)return false;try{localStorage.setItem(key,JSON.stringify(state));return true;}catch{toast('浏览器未能保存进度，请导出存档，避免关闭后丢失。');return false;}}
  function toast(t){$('toast').textContent=t;$('toast').classList.add('show');if(dialog.open){let notice=dialog.querySelector('.inline-notice');if(!notice){notice=document.createElement('p');notice.className='hint-box inline-notice';notice.setAttribute('role','status');dialog.querySelector('.lesson-main').append(notice);}notice.textContent=t;}clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('toast').classList.remove('show');dialog.querySelector('.inline-notice')?.remove();},5500);}
  function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
  function ask(text,action){$('confirm-text').textContent=text;$('confirm-dialog').showModal();$('confirm-ok').onclick=()=>{$('confirm-dialog').close();action();};$('confirm-cancel').onclick=()=>$('confirm-dialog').close();}
  function heroByName(name){return heroes.find(h=>h.name===name)||heroes[0];}
  function companion(c){return heroByName(state.hero || c?.hero || '李白');}
  function allChapters(){return [...course.chapters,...state.custom];}
  function available(c){return allChapters().some(x=>x.id===c.id);}
  function played(){return course.chapters.filter(c=>Object.hasOwn(state.cleared,c.id)).length;}
  function nextChapter(){return course.chapters.find(c=>!Object.hasOwn(state.cleared,c.id)&&available(c))||course.chapters[0];}
  function stars(n){return '★'.repeat(n)+'☆'.repeat(3-n);}
  function updateChrome(){
    const xp=state.earned.length*10,level=Math.floor(xp/100)+1;
    $('xp').textContent=`✦ ${xp} 星辉`;$('rank').textContent=`${level<3?'启程学徒':level<6?'知识探险家':'稷下学者'} · Lv.${level}`;
    $('level-bar').style.width=`${xp%100}%`;$('level-note').textContent=`距离下一级还需 ${100-xp%100} 星辉`;
    $('wrong-count').textContent=Object.keys(state.wrong).length;
    $('sound-button').innerHTML=`♫ <span>${state.sound?'声音开启':'声音关闭'}</span>`;
    $('sound-button').setAttribute('aria-label',state.sound?'关闭声音':'打开声音');
    $('sound-button').title=state.sound?'关闭声音':'打开声音';
    $('sound-button').setAttribute('aria-pressed',String(state.sound));
    document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
    $('location').textContent='探索 · '+({adventure:'冒险地图',practice:'试炼之地',heroes:'同行英雄',notebook:'知识手册',textbook:'我的教材'}[view]);
  }
  function playVoice(h,role='entry',force=false){
    if(!state.sound&&!force)return;
    const clip=typeof role==='number'?h.audio[role%h.audio.length]:h.voiceRoles?.[role];
    if(!clip){toast('暂未找到这位英雄的对应语音。');return;}
    voice.setVolume(state.volume);
    voice.play(clip.file).then(played=>{if(played&&force)toast(h.name+'：'+clip.text);}).catch(()=>toast('声音暂未播放，可点“重听”重试。首次访问请等待语音准备完成。'));
    voice.warm(h);
  }
  function setView(name){view=name;location.hash=name;render();$('main').focus({preventScroll:true});}
  function title(eyebrow,heading,detail=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${heading}</h1></div><span class="edition">五年级 · 课文与英语主题</span></div>${detail?`<p class="section-intro">${detail}</p>`:''}`;}
  function render(){updateChrome();const fn={adventure:renderHome,practice:renderPractice,heroes:renderHeroes,notebook:renderNotebook,textbook:renderTextbook};$('main').innerHTML=fn[view]();
    if(view==='adventure')$('main').insertAdjacentHTML('beforeend',`<section class="panel share-card"><img src="assets/learning-qr.png" alt="五年级学习网页二维码"><div><h3>壶兰呼吸 小学五年级知识</h3><p>by 崔逸林爸爸</p><p class="muted">仅限个人学习，不得进行商业化应用</p><a href="assets/learning-card.png" download="壶兰呼吸-五年级学习二维码.png">保存带注释的二维码 ↗</a></div></section>`);
    if(view==='heroes')$('main').insertAdjacentHTML('beforeend','<p class="voice-note">语音为英雄已有原声，来自不同皮肤与原始情境；用于学习中的开场、赞赏或鼓励，按原句播放，并非专门录制的答题配音。</p>');
    if(storageError)$('main').insertAdjacentHTML('afterbegin',`<div class="info-banner">${esc(storageError)} <button class="secondary" data-action="raw-save">导出原始存档</button> <button class="secondary" data-action="storage-reset">开始新存档</button></div>`);bindView();}
  function chapterCard(c,i){const h=heroByName(c.hero),result=state.cleared[c.id],unlocked=available(c);return `<button class="chapter-card" data-chapter="${esc(c.id)}" ${unlocked?'':'disabled'} aria-label="${esc(c.title)}，${result?'已通关':unlocked?'可挑战':'请先完成本学科前一关'}"><div class="chapter-art"><img src="assets/${h.image}" alt="" loading="lazy"><span class="chapter-number">${String(c.lessonNumber||i+1).padStart(2,'0')}</span></div><div class="chapter-content"><span class="tag">${esc(c.subject)} · ${esc(c.semester||c.region)}</span><h3>${esc(c.title.split(' · ').pop())}</h3><p>${esc(c.knowledge.slice(0,2).join(' / '))}</p><div class="chapter-status"><span class="${unlocked?'':'locked'}">${result?stars(result.stars):unlocked?'开启挑战 →':'完成前一关解锁'}</span><span>${c.questions.length} 道题</span></div></div></button>`;}
  function renderHome(){const c=nextChapter(),resume=state.session&&!state.session.finished,h=heroByName(c.hero),act=state.activity.date===day()?state.activity:{};
    return `<section class="brand-banner"><img src="assets/hulan-logo.jpg" alt="壶兰呼吸官方 LOGO"><div><h2>壶兰呼吸</h2><p>by 五年级崔逸林同学的爸爸</p></div><span class="personal-notice">仅限个人学习，不得进行商业化应用</span></section>`+title('CHAPTERS OF KNOWLEDGE','每一个答案，<span>都是新的冒险。</span>')+`<div class="home-grid"><div><section class="journey-hero"><img class="scene" src="assets/${h.image}" alt="${h.name} · ${h.skin}"><div class="scene-shade"></div><div class="hero-copy"><div class="pill">第一季 · 失落的知识晶石</div><p class="eyebrow">${played()===course.chapters.length?'THE JOURNEY CONTINUES':'YOUR NEXT CHAPTER'}</p><h2>${played()===course.chapters.length?'知识晶石归位':'书卷启程'}<br>${played()===course.chapters.length?'向新的知识出发':'点亮稷下星图'}</h2><p>${resume?`上次的旅程：${esc(state.session.title)}`:`与${h.name}同行，探索${esc(c.region)}。`}<br>${resume?'已经保存进度，随时接着学。':`下一站 · ${esc(c.title.split(' · ').pop())}`}</p><button class="primary" data-action="${resume?'resume':'recommended'}">${resume?'继续上次学习':played()===course.chapters.length?'再访故事':'开启知识冒险'} <span>→</span></button><div class="hero-meta">语文 · 数学 · 奥数 · 英语 <span>每关约 5 分钟</span></div></div><div class="scene-credit">${h.name} · ${h.skin}</div></section><section class="chapter-section"><div class="section-heading"><div><h2>探索你的知识版图</h2><p>自由选择主题，点击即听英雄开场。答对至少 60% 即可点亮晶石。</p></div><span>${played()} / ${course.chapters.length} 关</span></div><div class="filter-row" role="group" aria-label="学科筛选">${['全部',...E.subjects].map(x=>`<button class="filter ${filter===x?'active':''}" data-filter="${x}" aria-pressed="${filter===x}">${x==='英语'?'剑桥英语':x}</button>`).join('')}</div>${filter==='语文'?`<div class="filter-row semester-row" aria-label="语文册别">${['全部','上册','下册'].map(x=>`<button class="filter ${semester===x?'active':''}" data-semester="${x}" aria-pressed="${semester===x}">${x}</button>`).join('')}</div><p class="section-intro">统编版五年级 · 一课一个主题，先读原文再挑战。<br>${esc(course.languageEdition||'')}</p>`:filter==='英语'?'<p class="section-intro">剑桥英语能力路线 · A1 Movers → A2 Flyers 基础过渡。原创学习材料，不是剑桥官方教材；可根据实际掌握情况选择主题。</p>':''}<div class="chapter-grid">${course.chapters.map((x,i)=>(filter==='全部'||x.subject===filter)&&(filter!=='语文'||semester==='全部'||x.semester===semester)?chapterCard(x,i):'').join('')}</div></section></div><aside class="right-rail"><section class="rail-card"><p class="eyebrow">TODAY'S QUEST</p><h2>今日修炼</h2><p>不必匆忙，理解比速度重要。</p>${[[act.completed>0,'完成一段故事','或通过一次试炼'],[act.answered>0,'解开一道谜题','今天已答 '+(act.answered||0)+' 题'],[act.reviewed>0,'再看一次错题','答对复习题，巩固知识']].map((x,i)=>`<div class="daily-item ${x[0]?'done':''}"><span>${x[0]?'✓':'0'+(i+1)}</span><div>${x[1]}<small>${x[2]}</small></div></div>`).join('')}</section><section class="rail-card sage"><p class="eyebrow">A LITTLE REMINDER</p><h2>遇到难题也没关系</h2><p>看看提示，试着画一画，再读一遍。每次思考都值得被看见。</p><span class="ornament">✧</span></section><section class="rail-card"><div class="profile"><img src="assets/${h.avatar}" width="44" height="44" style="border-radius:9px" alt=""><div>同行 · ${h.name}<small>主题英雄 · 原声陪伴</small></div></div><button class="subtle" data-go="heroes">选择同行英雄 →</button></section></aside></div>`;
  }
  function renderPractice(){return title('THE TRAINING GROUNDS','试炼之地','随时练习，不受故事进度限制。每次六题，先思考，再看解析。')+`<div class="cards-grid"><section class="panel practice-card"><span class="card-icon">Aa</span><h2>剑桥英语基础过渡</h2><p>从校园与购物到过去经历和短篇故事。8 个主题，每课先读英文原文，再练词汇与句型。</p><button class="primary" data-action="english-module">进入英语主题 →</button></section><section class="panel practice-card"><span class="card-icon">＋</span><h2>数学日常修炼</h2><p>小数乘除、简易方程与多边形面积。每次进入，生成一组新题。</p><button class="primary" data-practice="数学">开始数学试炼 →</button></section><section class="panel practice-card"><span class="card-icon">◇</span><h2>奥数思维挑战</h2><p>和差、鸡兔同笼、周期、计数与相遇问题。提示帮你找到第一步。</p><button class="primary" data-practice="奥数">开始奥数试炼 →</button></section><section class="panel practice-card"><span class="card-icon">↺</span><h2>错题再出发</h2><p>还有 ${Object.keys(state.wrong).length} 道题等你掌握。答对后会自动移出错题本。</p><button class="secondary" data-action="review" ${Object.keys(state.wrong).length?'':'disabled'}>开始错题复习</button></section></div><div class="info-banner" style="margin-top:25px">没有倒计时，也不会扣生命值。同一道题首次答对获得 10 星辉；重复练习帮助巩固，不重复计分。</div>`;}
  function renderHeroes(){return title('YOUR COMPANIONS','与英雄，一起成长','故事关卡使用主题中的英雄；你也可以为自由试炼选择伙伴。开场、答对赞赏和答错鼓励均使用同一位英雄的原声。')+`<div class="button-row" style="margin-bottom:23px"><button class="secondary" data-action="auto-hero">${state.hero?'试炼恢复默认英雄':'✓ 试炼使用默认英雄'}</button><label for="volume" style="margin:0">音量</label><input id="volume" aria-label="语音音量" type="range" min="0" max="100" value="${Math.round(state.volume*100)}" style="width:160px;min-height:30px"></div><div class="cards-grid">${heroes.map(h=>`<section class="panel hero-card ${state.hero===h.name?'selected':''}"><img src="assets/${h.image}" alt="${h.name} · ${h.skin}" loading="lazy"><div class="hero-card-body"><span class="tag">${h.skin}</span><h2>${h.name}</h2><p>“${esc(h.audio[0].text)}”</p><div class="button-row"><button class="primary" data-hero="${h.name}">${state.hero===h.name?'✓ 已选择':'与我同行'}</button>${Object.entries(h.voiceRoles).map(([role,v])=>`<button class="secondary" data-listen="${h.id}:${role}" aria-label="试听${h.name}${({entry:'开场',praise:'赞赏',encourage:'鼓励'})[role]}" title="${esc(v.text)}">♫ ${({entry:'开场',praise:'赞赏',encourage:'鼓励'})[role]}</button>`).join('')}</div></div></section>`).join('')}</div>`;}
  function renderNotebook(){const entries=Object.values(state.wrong);return title('YOUR KNOWLEDGE JOURNAL','把不会，变成学会。')+`<div class="stats-row"><div class="stat"><strong>${state.earned.length}</strong><span>首次答对的题目</span></div><div class="stat"><strong>${played()} / ${course.chapters.length}</strong><span>已通过故事关卡</span></div><div class="stat"><strong>${entries.length}</strong><span>等待巩固的错题</span></div></div><div class="section-heading"><div><h2>错题收藏</h2><p>先再想一次，再展开解析。正确复习后会自动移出。</p></div><button class="secondary" data-action="review" ${entries.length?'':'disabled'}>复习全部</button></div><div class="note-list">${entries.length?entries.map(x=>`<article class="panel note-card"><span class="tag">${esc(x.subject)} · ${esc(x.question.skill)} · ${esc(x.chapterTitle)}</span><h3>${esc(x.question.prompt)}</h3>${x.question.passage?`<div class="passage">${esc(x.question.passage)}</div>`:''}<details><summary>查看答案与思路</summary><p>答案：${esc(E.answerText(x.question))}</p><p>${esc(x.question.explanation)}</p></details><button class="subtle" data-review-one="${esc(x.question.id)}">再挑战这道题 →</button></article>`).join(''):'<div class="empty">错题本空空的。继续探索，遇到难题时，它会替你记下来。</div>'}</div><section class="chapter-section"><div class="section-heading"><h2>知识要点</h2></div><div class="note-list">${allChapters().filter(c=>Object.hasOwn(state.cleared,c.id)).map(c=>`<article class="panel note-card"><h3>${esc(c.title)}</h3><ul class="knowledge-list">${c.knowledge.map(k=>`<li>${esc(k)}</li>`).join('')}</ul></article>`).join('')||'<p class="muted">通过关卡后，对应知识要点会点亮在这里。</p>'}</div></section>`;}
  function renderTextbook(){return title('YOUR OWN TEXTBOOK','让课本，走进故事。')+`<div class="info-banner">内置语文按统编版五年级上下册逐课组织，提供官方教材原文入口；英语是参照剑桥 A1–A2 能力范围的原创课程。可粘贴课文、添加题目并选择英雄，生成自己的学习关卡。此入口由你填写并核对题目，不会自动识别教材或调用 AI。</div><div class="split-panel"><section class="panel"><div class="section-heading"><h2>创建教材关卡</h2><button class="subtle" data-action="load-example">填入示例</button></div><form id="course-form"><div class="form-grid"><div><label for="course-title">课程名称</label><input id="course-title" maxlength="100" required placeholder="如：五年级语文 · 观察日记"></div><div><label for="course-subject">学科</label><select id="course-subject">${E.subjects.map(x=>`<option>${x}</option>`).join('')}</select></div><div><label for="course-hero">陪伴英雄</label><select id="course-hero">${heroes.map(x=>`<option>${x.name}</option>`).join('')}</select></div><div><label for="text-file">导入课文文本（TXT）</label><input id="text-file" type="file" accept=".txt,text/plain"></div><div class="wide"><label for="course-passage">教材原文 / 阅读材料</label><textarea id="course-passage" rows="5" maxlength="30000" placeholder="粘贴你正在学习的课文。仅保存在本机浏览器中。"></textarea></div><div class="wide"><label for="course-story">故事开场</label><textarea id="course-story" rows="2" maxlength="30000" placeholder="英雄在书院里发现了一封信，请你读懂它，找到线索。"></textarea></div><div class="wide"><label for="course-knowledge">知识要点（每行一条）</label><textarea id="course-knowledge" rows="2" placeholder="联系上下文理解词语&#10;提取短文中的关键信息"></textarea></div></div><div id="editor-questions">${questionEditor(0)}</div><div class="button-row"><button type="button" class="secondary" data-action="add-question">＋ 添加题目</button><button type="submit" class="primary">保存为学习关卡</button></div><p class="form-help">支持 1–30 道题。阅读题使用上面的教材原文。保存前请核对答案与解析。</p></form></section><div><section class="panel"><h2>我的课程 · ${state.custom.length}</h2>${state.custom.map(c=>`<div class="textbook-item"><div><h3>${esc(c.title)}</h3><p>${esc(c.subject)} · ${c.questions.length} 题</p></div><div class="button-row"><button class="secondary" data-chapter="${esc(c.id)}">学习</button><button class="subtle" data-export-course="${esc(c.id)}">导出</button><button class="subtle" data-delete-course="${esc(c.id)}">删除</button></div></div>`).join('')||'<p class="muted">添加第一课，让熟悉的知识加入旅程。</p>'}<label for="course-file" style="margin-top:24px">导入课程文件（JSON）</label><input type="file" id="course-file" accept=".json,application/json"><button class="subtle" data-action="course-template">下载课程模板 ↗</button></section><section class="panel" style="margin-top:22px"><h2>学习存档</h2><p class="form-help">进度保存在当前浏览器。换电脑、换浏览器或清理缓存前，请先导出。导入会替换现有存档。</p><div class="button-row"><button class="secondary" data-action="backup">导出存档</button><button class="secondary" data-action="restore">导入存档</button></div><p class="form-help">存档含课程、成绩与错题；当前未完成的一轮不包含在导出中。</p></section></div></div>`;}
  function questionEditor(i,q){return `<fieldset class="editor-question"><legend>题目 ${i+1}</legend><div class="form-grid"><div><label>题型<select class="q-type" aria-label="题目${i+1}题型"><option value="choice">选择题</option><option value="boolean">判断题</option><option value="reading">阅读理解</option><option value="number">数字填空</option></select></label></div><div><label>知识点<input class="q-skill" maxlength="100" placeholder="如：提取信息"></label></div><div class="wide"><label>题干<textarea class="q-prompt" required rows="2" maxlength="2000"></textarea></label></div><div class="wide q-options-wrap"><label>选项（每行一个）<textarea class="q-options" rows="3" maxlength="12000" placeholder="选项一&#10;选项二&#10;选项三"></textarea></label></div><div><label class="q-answer-label">正确答案序号（从 1 开始）<input class="q-answer" required inputmode="decimal" placeholder="如：2"></label></div><div><label>思考提示<input class="q-hint" maxlength="2000" placeholder="引导孩子找到思路"></label></div><div class="wide"><label>答案解析<textarea class="q-explanation" required rows="2" maxlength="6000"></textarea></label></div></div><button type="button" class="subtle remove-question">移除此题</button></fieldset>`;}
  function bindView(){
    $('main').querySelectorAll('[data-semester]').forEach(b=>b.onclick=()=>{semester=b.dataset.semester;render();});
    $('main').querySelectorAll('[data-chapter]').forEach(b=>{const warm=()=>{if(state.sound){const c=allChapters().find(c=>c.id===b.dataset.chapter);if(c)voice.warm(heroByName(c.hero));}};b.onpointerenter=warm;b.onpointerdown=warm;b.onfocus=warm;});
    $('main').querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>startChapter(b.dataset.chapter));
    $('main').querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});
    $('main').querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>setView(b.dataset.go));
    $('main').querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>startPractice(b.dataset.practice));
    $('main').querySelectorAll('[data-listen]').forEach(b=>b.onclick=()=>{const [id,role]=b.dataset.listen.split(':');playVoice(heroes.find(h=>h.id===id),role,true);});
    $('main').querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{state.hero=b.dataset.hero;persist();render();toast(`已选择${state.hero}与你同行。`);});
    $('main').querySelectorAll('[data-review-one]').forEach(b=>b.onclick=()=>startReview(b.dataset.reviewOne));
    $('main').querySelectorAll('[data-export-course]').forEach(b=>b.onclick=()=>{const c=state.custom.find(x=>x.id===b.dataset.exportCourse);download({version:1,chapters:[c]},'稷下课程-'+c.title+'.json');});
    $('main').querySelectorAll('[data-delete-course]').forEach(b=>b.onclick=()=>ask('删除此自建课程？建议先导出课程备份。关联的待复习错题也将移除。',()=>{const c=state.custom.find(x=>x.id===b.dataset.deleteCourse);for(const q of c.questions)delete state.wrong[q.id];state.custom=state.custom.filter(x=>x.id!==c.id);delete state.cleared[c.id];if(state.session?.chapterId===c.id)state.session=null;persist();render();}));
    $('main').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
    if($('volume'))$('volume').oninput=e=>{state.volume=Number(e.target.value)/100;voice.setVolume(state.volume);persist();};
    if($('course-form')){
      $('course-form').onsubmit=saveCourse;wireEditor();
      $('text-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>120000)throw new Error('请导入 120 KB 以内的 UTF-8 文本。');const text=await file.text();if(text.length>30000)throw new Error('课文请控制在 30000 字以内。');$('course-passage').value=text;toast('课文已载入，请添加对应题目和解析。');}catch(err){toast(err.message);}finally{e.target.value='';}};
      $('course-file').onchange=importCourses;
    }
  }
  function action(a){
    if(a==='recommended')startChapter(nextChapter().id);
    else if(a==='resume'){session=state.session;renderLesson();dialog.showModal();playVoice(heroByName(session.hero),'entry');}
    else if(a==='english-module'){filter='英语';setView('adventure');document.querySelector('.chapter-section')?.scrollIntoView({block:'start'});}
    else if(a==='review')startReview();
    else if(a==='auto-hero'){state.hero=null;persist();render();}
    else if(a==='backup')download(E.backup(state),'稷下学习存档-'+day()+'.json');
    else if(a==='restore')$('restore-input').click();
    else if(a==='add-question'){const n=document.querySelectorAll('.editor-question').length;if(n>=30){toast('每关最多 30 道题。');return;}$('editor-questions').insertAdjacentHTML('beforeend',questionEditor(n));wireEditor();}
    else if(a==='course-template')download({version:1,chapters:[sampleCourse()]},'稷下课程模板.json');
    else if(a==='load-example')fillExample();
    else if(a==='raw-save'){try{download(localStorage.getItem(key)||'{}','稷下原始存档.json');}catch{toast('浏览器禁止读取存档。');}}
    else if(a==='storage-reset')ask('建议先导出原始存档。确定用当前新旅程替换无法读取的存档吗？',()=>{storageError='';persist();render();});
  }
  function withNewSession(start){if(state.session&&!state.session.finished){ask('已有一轮尚未完成。开启新挑战会替换这一轮的答题位置；已获得星辉和错题记录仍会保留。',start);}else start();}
  function startChapter(id){const c=allChapters().find(x=>x.id===id);if(!c||!available(c)){toast('未找到这个主题。');return;}withNewSession(()=>openSession({mode:'story',chapterId:c.id,title:c.title,subject:c.subject,hero:heroByName(c.hero).name,story:c.story,ending:c.ending,knowledge:c.knowledge,passage:state.texts[c.id]||c.passage||'',readingTitle:c.readingTitle,readingSource:state.texts[c.id]?'你保存在本机的课文原文':c.readingSource,sourceUrl:c.sourceUrl,questions:c.questions}));}
  function startPractice(subject){withNewSession(()=>openSession({mode:'practice',title:subject==='数学'?'数学日常修炼':'奥数思维挑战',subject,hero:companion({hero:'诸葛亮'}).name,story:'这一次，让我们用学过的方法解决六个新问题。慢慢想，不着急；遇到困难时可以打开提示。',ending:'每次练习都在让思路更清晰。你可以再来一组新题，或回到故事中继续探索。',knowledge:['先读条件，再想方法。','画图、列式，最后代回题目检查。'],questions:E.makePractice(subject)}));}
  function startReview(id){let entries=id?[state.wrong[id]].filter(Boolean):Object.values(state.wrong).slice(0,30);if(!entries.length){toast('目前没有需要复习的错题。');return;}withNewSession(()=>openSession({mode:'review',title:'错题再出发',subject:entries[0].subject,hero:heroByName(entries[0].hero).name,questionHeroes:entries.map(x=>heroByName(x.hero).name),story:`这一轮复习 ${entries.length} 道题。答对后它们会移出错题本；暂时没想明白也没关系，可以继续看解析。`,ending:'复习完成。理解思路，比记住选项更重要。',knowledge:['想想上次是哪一步没看清楚。','重新独立作答，确认已经理解。'],questions:entries.map(x=>x.question)}));}
  function openSession(s){voice.stop();session={...s,index:0,correct:0,gained:0,checked:false,selection:null,hinted:false,phase:'story',finished:false};state.session=session;persist();renderLesson();dialog.showModal();playVoice(heroByName(s.hero),'entry');}
  function readingPanel(s,open){
    if(!s.passage&&!s.sourceUrl)return '';
    const original=s.subject==='英语'?'英文学习原文':'课文原文';
    return '<details class="lesson-reading" '+(open?'open':'')+'><summary>'+original+' · '+esc(s.readingTitle||s.title)+'</summary>'+
      (s.readingSource?'<p class="form-help">'+esc(s.readingSource)+'</p>':'')+
      (s.passage?'<div class="passage" lang="'+(s.subject==='英语'?'en':'zh-CN')+'">'+esc(s.passage)+'</div>':'<p class="form-help">点击下方入口阅读官方教材原文；本页未转载该篇现代课文全文。</p>')+
      (s.sourceUrl?'<a class="secondary source-link" href="'+esc(s.sourceUrl)+'" target="_blank" rel="noopener noreferrer">打开人教社电子教材（选择本册） ↗</a>':'')+
      (s.chapterId&&s.subject==='语文'?'<details class="local-reading-editor"><summary>把自己的本课原文保存在这里</summary><label for="local-passage">粘贴课文原文（仅保存在本机，随学习存档导出）</label><textarea id="local-passage" rows="8" maxlength="30000">'+esc(state.texts[s.chapterId]||'')+'</textarea><button class="secondary" id="save-local-passage">保存本课原文</button><span id="reading-save-status" role="status"></span></details>':'')+'</details>';
  }
  function wireReading(){if($('save-local-passage'))$('save-local-passage').onclick=()=>{const value=$('local-passage').value.trim();if(!value){toast('请先粘贴本课原文。');return;}state.texts[session.chapterId]=value;session.passage=value;session.readingSource='你保存在本机的课文原文';if(persist()){renderLesson();toast('本课原文已保存，可边读边答题。');}};}
  function renderLesson(){if(!session)return;const s=session,h=heroByName(s.hero),q=s.questions[s.index];
    let body='';
    if(s.phase==='story')body=`<p class="question-meta">${esc(s.subject)} · ${s.questions.length} 道题</p><h2 class="question-heading">${esc(s.title)}</h2><p class="story-text">${esc(s.story)}</p>${readingPanel(s,true)}<h3 style="margin-top:25px">这一站，你将学会</h3><ul class="knowledge-list">${s.knowledge.map(k=>`<li>${esc(k)}</li>`).join('')}</ul><div class="lesson-actions"><span class="muted">理解比速度更重要</span><button class="primary" id="begin-question">进入挑战 →</button></div>`;
    else if(s.phase==='result')body=`<div class="result"><div class="result-mark" aria-label="${s.stars}颗星">${stars(s.stars)}</div><h2>${s.passed?'知识晶石已点亮':'休息一下，再试一次'}</h2><p>${s.passed?esc(s.ending):'这一次暂未达到 60%。看看错题的思路，再回来挑战；已经答对的知识不会丢失。'}</p><div class="stats-row"><div class="stat"><strong>${s.correct}/${s.questions.length}</strong><span>本轮答对</span></div><div class="stat"><strong>+${s.gained}</strong><span>新增星辉</span></div><div class="stat"><strong>${s.questions.length-s.correct}</strong><span>本轮错题</span></div></div><div class="button-row" style="justify-content:center"><button class="secondary" id="exit-result">返回地图</button><button class="primary" id="result-next">${s.mode==='practice'?'再来一组':s.mode==='review'?'回到知识手册':s.passed?'继续旅程 →':'重试这一关'}</button></div></div>`;
    else body=`<div class="lesson-progress" aria-label="第 ${s.index+1} 题，共 ${s.questions.length} 题">${s.questions.map((_,i)=>`<span class="${i<s.index?'passed':i===s.index?'current':''}"></span>`).join('')}</div><p class="question-meta">${({choice:'选择题',boolean:'判断题',reading:'阅读理解',number:'数字填空'})[q.type]} · ${esc(q.skill)} <span class="muted">${s.index+1} / ${s.questions.length}</span></p>${readingPanel(s,false)}${q.passage&&q.passage!==s.passage?`<div class="passage">${esc(q.passage)}</div>`:''}<h2 class="question-heading" id="question-prompt">${esc(q.prompt)}</h2>${q.type==='number'?`<label for="numeric-answer">输入答案（只填数字，不带单位）</label><input id="numeric-answer" inputmode="decimal" autocomplete="off" maxlength="30" value="${esc(s.selection??'')}" ${s.checked?'disabled':''}>`:`<div class="options" role="group" aria-labelledby="question-prompt">${q.options.map((o,i)=>`<button class="answer-option ${s.selection===i?'selected':''} ${s.checked&&i===q.answer?'correct':''} ${s.checked&&s.selection===i&&i!==q.answer?'wrong':''}" data-answer="${i}" ${s.checked?'disabled':''} aria-pressed="${s.selection===i}"><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span></button>`).join('')}</div>`}${s.hinted?`<div class="hint-box">提示：${esc(q.hint)}</div>`:''}${s.checked?`<div class="feedback ${s.feedback?'':'wrong'}" role="status"><h3>${s.feedback?'✓ 思路正确，继续前进！':'换个思路，我们一起看一看'}</h3><p>正确答案：${esc(E.answerText(q))}</p><p>${esc(q.explanation)}</p></div>`:''}<div class="lesson-actions"><button class="subtle" id="hint-button" ${s.hinted?'disabled':''}>${s.hinted?'提示已展开':'✧ 给我一点提示'}</button><button class="primary" id="submit-answer">${s.checked?(s.index===s.questions.length-1?'查看本轮收获':'下一题 →'):'确认答案'}</button></div>`;
    dialog.innerHTML=`<div class="lesson-layout"><aside class="lesson-sidebar"><img src="assets/${h.image}" alt="${h.name} · ${h.skin}"><span class="pill">知识远征 · ${esc(s.subject)}</span><div class="hero-identity"><p class="eyebrow">YOUR COMPANION</p><h2>${h.name}</h2><p>认真思考的你，就是这段旅程的主角。</p><button class="secondary" id="lesson-voice">♫ 听听英雄的声音</button><p class="form-help">${esc(h.audio[0].text)}</p></div></aside><section class="lesson-main"><div class="lesson-top"><span class="eyebrow">${s.phase==='result'?'CHAPTER COMPLETE':'THE KNOWLEDGE QUEST'}</span><button class="close-button" id="close-lesson" aria-label="保存并退出关卡">×</button></div><p class="voice-status" data-voice-status role="status">${esc(voiceStatus)}</p>${body}</section></div>`;
    wireReading();$('close-lesson').onclick=closeLesson;$('lesson-voice').onclick=()=>playVoice(h,'entry',true);
    const mobileVoice=document.createElement('button');mobileVoice.className='subtle mobile-voice';mobileVoice.type='button';mobileVoice.textContent=`♫ ${h.name} · 重听开场`;mobileVoice.onclick=()=>playVoice(h,'entry',true);dialog.querySelector('.lesson-top').prepend(mobileVoice);
    if(s.checked&&s.phase==='question'){
      const role=s.feedback?'praise':'encourage',clip=h.voiceRoles?.[role];
      const panel=document.createElement('div');panel.className='voice-feedback';panel.innerHTML=`<img src="assets/${h.avatar}" alt=""><div><strong>${h.name} · ${s.feedback?'原声赞赏':'原声鼓励'}</strong><p>“${esc(clip?.text||'')}”</p></div><button class="secondary" id="replay-feedback">♫ 重听</button>`;
      dialog.querySelector('.feedback').append(panel);$('replay-feedback').onclick=()=>playVoice(h,role,true);
    }
    if($('begin-question'))$('begin-question').onclick=()=>{s.phase='question';persist();renderLesson();focusQuestion();};
    dialog.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{s.selection=Number(b.dataset.answer);persist();renderLesson();dialog.querySelector(`[data-answer="${s.selection}"]`).focus({preventScroll:true});});
    if($('numeric-answer')){$('numeric-answer').oninput=e=>{s.selection=e.target.value;};$('numeric-answer').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();submitAnswer();}};}
    if($('hint-button'))$('hint-button').onclick=()=>{s.hinted=true;persist();renderLesson();focusQuestion();};
    if($('submit-answer'))$('submit-answer').onclick=submitAnswer;
    if($('exit-result'))$('exit-result').onclick=()=>{closeLesson();setView('adventure');};
    if($('result-next'))$('result-next').onclick=()=>{const old=s;closeLesson();if(old.mode==='practice')startPractice(old.subject);else if(old.mode==='review')setView('notebook');else if(!old.passed)startChapter(old.chapterId);else{const group=allChapters().filter(c=>c.subject===old.subject);const i=group.findIndex(c=>c.id===old.chapterId);if(group[i+1])startChapter(group[i+1].id);else{setView('adventure');toast('这条学科路线已完成，去探索另一条路线吧！');}}};
  }
  function focusQuestion(){const heading=dialog.querySelector('.question-heading,.result h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}
  function submitAnswer(){const s=session,q=s.questions[s.index];if(s.checked){if(s.index===s.questions.length-1){E.completeSession(state,s);if(s.passed)playVoice(heroByName(s.hero),'praise');}else{voice.stop();s.index++;if(Array.isArray(s.questionHeroes))s.hero=heroByName(s.questionHeroes[s.index]).name;s.selection=null;s.checked=false;s.feedback=null;s.hinted=false;}persist();renderLesson();focusQuestion();dialog.scrollTop=0;return;}
    if(s.selection===null || q.type==='number'&&E.numeric(s.selection)===null){toast(q.type==='number'?'请输入一个有效数字，不需要填写单位。':'先选择一个答案，再点击确认。');return;}
    const outcome=E.scoreSession(state,s,q,s.selection,day());persist();updateChrome();renderLesson();if(outcome)playVoice(heroByName(s.hero),outcome.correct?'praise':'encourage');$('submit-answer').focus({preventScroll:true});
  }
  function closeLesson(){voice.stop();if(session?.finished)state.session=null;persist();dialog.close();session=null;render();}
  dialog.addEventListener('cancel',e=>{e.preventDefault();closeLesson();});
  function wireEditor(){document.querySelectorAll('.editor-question').forEach((el,i)=>{
    el.querySelector('legend').textContent=`题目 ${i+1}`;
    el.querySelector('.remove-question').onclick=()=>{if(document.querySelectorAll('.editor-question').length===1){toast('至少保留一道题。');return;}el.remove();wireEditor();};
    el.querySelector('.q-type').onchange=()=>{const type=el.querySelector('.q-type').value;el.querySelector('.q-options-wrap').hidden=type==='number';const opts=el.querySelector('.q-options');opts.readOnly=type==='boolean';if(type==='boolean')opts.value='正确\n错误';el.querySelector('.q-answer-label').firstChild.textContent=type==='number'?'正确数字答案':'正确答案序号（从 1 开始）';};
  });}
  function sampleCourse(){return {id:'sample-reading',title:'观察日记 · 一株豆苗',subject:'语文',hero:'李白',region:'我的教材',story:'李白发现一本观察日记。读一读，帮他找到豆苗生长的线索。',ending:'认真观察，也是一种发现世界的方法。',knowledge:['从原文提取信息','区分事实与猜测'],passage:'周一，我把豆子放在湿棉花上。周三，豆子裂开一条小缝，露出了白色的小根。周五，小芽向上伸展。我每天给棉花加一点水，并把变化画在本子上。',questions:[{id:'sample-q1',type:'reading',prompt:'小根最早在哪一天出现？',passage:'周一，我把豆子放在湿棉花上。周三，豆子裂开一条小缝，露出了白色的小根。周五，小芽向上伸展。',options:['周一','周三','周五'],answer:1,hint:'在文中找一找“白色的小根”。',explanation:'原文说周三豆子露出了白色的小根，因此选择周三。',skill:'提取信息'}]};}
  function fillExample(){const c=sampleCourse();$('course-title').value=c.title;$('course-subject').value=c.subject;$('course-hero').value=c.hero;$('course-passage').value=c.passage;$('course-story').value=c.story;$('course-knowledge').value=c.knowledge.join('\n');$('editor-questions').innerHTML=questionEditor(0);wireEditor();const el=document.querySelector('.editor-question'),q=c.questions[0];for(const [field,value] of Object.entries({type:q.type,prompt:q.prompt,options:q.options.join('\n'),answer:q.answer+1,hint:q.hint,explanation:q.explanation,skill:q.skill}))el.querySelector('.q-'+field).value=value;el.querySelector('.q-type').dispatchEvent(new Event('change'));toast('已填入原创示例，你可以修改为自己的教材内容。');}
  const newId=()=>`custom-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
  function saveCourse(event){event.preventDefault();try{
    if(state.custom.length>=50)throw new Error('最多保留 50 个自建课程，请先导出并整理旧课程。');
    const passage=$('course-passage').value.trim(),id=newId();
    const questions=[...document.querySelectorAll('.editor-question')].map((el,i)=>{const val=k=>el.querySelector('.q-'+k).value.trim(),type=val('type');return {id:`${id}-q${i+1}`,type,prompt:val('prompt'),options:type==='boolean'?['正确','错误']:val('options').split('\n').map(x=>x.trim()).filter(Boolean),answer:type==='number'?val('answer'):Number(val('answer'))-1,passage:type==='reading'?passage:undefined,explanation:val('explanation'),hint:val('hint'),skill:val('skill')};});
    const c=E.validateChapter({id,title:$('course-title').value,subject:$('course-subject').value,hero:$('course-hero').value,story:$('course-story').value,knowledge:$('course-knowledge').value.split('\n').filter(x=>x.trim()),passage,questions});state.custom.push(c);persist();render();toast('新关卡已保存，可以开始学习，也可以导出课程文件。');
  }catch(err){toast(err.message);}}
  async function importCourses(event){const file=event.target.files[0];if(!file)return;try{
    if(file.size>2*1024*1024)throw new Error('课程文件不能超过 2 MB。');const data=JSON.parse(await file.text());
    const list=Array.isArray(data.chapters)?data.chapters:[data];if(!list.length||list.length+state.custom.length>50)throw new Error('导入后课程总数须为 1–50。');
    const incoming=list.map(c=>E.validateChapter(c,newId()));state.custom.push(...incoming);persist();render();toast(`已导入 ${incoming.length} 个课程，原有课程已保留。`);
  }catch(err){toast('导入失败：'+err.message);}finally{event.target.value='';}}
  $('restore-input').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('存档不能超过 5 MB。');const restored=E.restore(JSON.parse(await file.text()));ask(`已验证存档：${restored.custom.length} 个自建课程、${restored.earned.length} 道已答对题目。确定替换当前存档吗？`,()=>{voice.stop();state=restored;session=null;storageError='';persist();render();toast('学习存档已导入。');});}catch(err){toast('无法导入存档：'+err.message);}finally{event.target.value='';}};
  document.querySelectorAll('nav [data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
  $('backup-button').onclick=()=>action('backup');
  $('sound-button').onclick=()=>{state.sound=!state.sound;if(!state.sound){voice.stop();}else playVoice(heroByName(nextChapter().hero),'entry');persist();updateChrome();};
  window.addEventListener('beforeunload',()=>{if(session&&!session.finished)state.session=session;persist();});
  window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['adventure','practice','heroes','notebook','textbook'].includes(next)&&view!==next){view=next;render();}});
  const initial=location.hash.slice(1);if(['adventure','practice','heroes','notebook','textbook'].includes(initial))view=initial;
  render();
  if(state.sound)voice.warmAll([heroByName(nextChapter().hero),...heroes.filter(h=>h.name!==nextChapter().hero)]);
  const context=document.modelContext;
  if(context?.registerTool){try{Promise.resolve(context.registerTool({name:'read_learning_progress',title:'查看学习进度',description:'读取本机学习进度与待复习题数，不修改数据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('无需输入参数。');return {chaptersCompleted:played(),chaptersTotal:course.chapters.length,mastered:state.earned.length,wrong:Object.keys(state.wrong).length};}})).catch(()=>{});}catch{}}
})();
